import { useEffect, useState } from "react";
import MenuGrid from "./MenuGrid";
import Cart from "./Cart";
import UserOrders from "./UserOrders";
import { useAuth } from "../../context/AuthContext";
import Recommendations from "./Recommendations";
import "../../styles/canteen-ui.css";

export default function UserPanel() {
  const { user, logout } = useAuth();
  const [cart, setCart] = useState([]);
  const [orders, setOrders] = useState([]);
  const [menu, setMenu] = useState([]);

  /* =========================
     CART LOGIC (quantity based)
  ========================= */

  const addToCart = item => {
    setCart(prev => {
      const existing = prev.find(i => i.id === item.id);

      if (existing) {
        return prev.map(i =>
          i.id === item.id ? { ...i, quantity: i.quantity + 1 } : i
        );
      }

      return [...prev, { ...item, quantity: 1 }];
    });
  };

  const removeFromCart = id => {
    setCart(prev =>
      prev
        .map(i =>
          i.id === id ? { ...i, quantity: i.quantity - 1 } : i
        )
        .filter(i => i.quantity > 0)
    );
  };

  /* =========================
     PLACE ORDER
  ========================= */

  const placeOrder = async () => {
    if (!user || cart.length === 0) return;

    const items = cart;
    const total = items.reduce(
      (sum, i) => sum + i.price * i.quantity,
      0
    );

    const order_id = Date.now();

    // Instant UI update
    setOrders(prev => [
      { order_id, items, total, status: "Pending" },
      ...prev
    ]);

    try {
      await fetch("http://127.0.0.1:8000/api/orders/create/", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          order_id,
          user: user.username,
          items,
          total
        })
      });

      setCart([]);

      // 🔄 Refresh menu stock immediately after order
     fetch(`http://localhost:8000/api/menu/?college=${user.college}`)
  .then(res => res.json())
  .then(setMenu);


    } catch (err) {
      console.error("Order failed", err);
    }
  };

  /* =========================
     MENU AUTO REFRESH
  ========================= */

  useEffect(() => {
    const loadMenu = () => {
      fetch("http://127.0.0.1:8000/api/menu/")
        .then(res => res.json())
        .then(setMenu)
        .catch(err => console.error("Menu fetch failed", err));
    };

    loadMenu();
    const interval = setInterval(loadMenu, 3000);

    return () => clearInterval(interval);
  }, []);

  /* =========================
     ORDER AUTO SYNC
  ========================= */

  useEffect(() => {
    if (!user) return;

    const syncOrders = () => {
      fetch(`http://127.0.0.1:8000/api/orders/?user=${user.username}`)
        .then(res => res.json())
        .then(setOrders)
        .catch(() => {});
    };

    syncOrders();
    const interval = setInterval(syncOrders, 2000);

    return () => clearInterval(interval);
  }, [user]);

  /* =========================
     UI
  ========================= */

  if (!user) return null;

  return (
    <div>
      <header>
        <h2>Welcome {user.username}</h2>
        <button onClick={logout}>Logout</button>
      </header>

      <Recommendations addToCart={addToCart} />
      <MenuGrid
        menu={menu}
        cart={cart}
        addToCart={addToCart}
  	removeFromCart={removeFromCart}
      />


      <Cart
        cart={cart}
        removeFromCart={removeFromCart}
        placeOrder={placeOrder}
      />

      <UserOrders orders={orders} />
    </div>
  );
}
